const bookSlugs = $node["Set Book Slugs"].json.book_slugs.split(',');
const tasks = [];

for (const bookSlug of bookSlugs) {
  tasks.push({
    book_slug: bookSlug.trim(),
    action: 'check_book'
  });
}

return tasks.map(task => ({ json: task }));

const axios = require('axios');

const bookSlug = $node["Generate Book Tasks"].json.book_slug;
const baseUrl = 'https://afghanbibles.org/eng/pashto-bible';

// Check if book exists and get chapter count
const firstChapterUrl = `${baseUrl}/${bookSlug}/${bookSlug}-1`;

try {
  const response = await axios.get(firstChapterUrl, {
    timeout: 30000,
    headers: {
      'User-Agent': 'PashtoBibleSearch-Monitor/1.0'
    }
  });

  // Extract chapter options from HTML
  const chapterMatches = response.data.match(/<option value="(\d+)">\1<\/option>/g);
  const chapters = chapterMatches ? chapterMatches.map(match => parseInt(match.match(/value="(\d+)"/)[1])) : [1];
  const maxChapter = Math.max(...chapters);

  const chapterTasks = [];
  for (let chapter = 1; chapter <= maxChapter; chapter++) {
    chapterTasks.push({
      book_slug: bookSlug,
      chapter: chapter,
      url: `${baseUrl}/${bookSlug}/${bookSlug}-${chapter}`,
      action: 'check_chapter'
    });
  }

  return chapterTasks.map(task => ({ json: task }));

} catch (error) {
  console.error(`Error checking book ${bookSlug}:`, error.message);
  return [{ json: { book_slug: bookSlug, error: error.message, action: 'error' } }];
}

const axios = require('axios');
const crypto = require('crypto');

const { book_slug, chapter, url } = $node["Check Book Chapters"].json;

try {
  const response = await axios.get(url, {
    timeout: 30000,
    headers: {
      'User-Agent': 'PashtoBibleSearch-Monitor/1.0'
    }
  });

  // Generate content hash
  const contentHash = crypto.createHash('sha256').update(response.data).digest('hex');

  // Extract last modified header
  const lastModified = response.headers['last-modified'] || null;

  return [{
    json: {
      book_slug,
      chapter,
      url,
      content_hash: contentHash,
      last_modified: lastModified,
      content_length: response.data.length,
      status_code: response.status,
      action: 'content_checked'
    }
  }];

} catch (error) {
  console.error(`Error checking chapter ${book_slug}:${chapter}:`, error.message);
  return [{
    json: {
      book_slug,
      chapter,
      url,
      error: error.message,
      status_code: error.response?.status || 0,
      action: 'error'
    }
  }];
}

const fs = require('fs');
const path = require('path');

const cacheFile = path.join(process.cwd(), 'external_content_cache.json');
let cache = {};

// Load existing cache
if (fs.existsSync(cacheFile)) {
  try {
    cache = JSON.parse(fs.readFileSync(cacheFile, 'utf8'));
  } catch (error) {
    console.error('Error loading cache:', error.message);
  }
}

// Process current content check
const current = $node["Fetch Chapter Content"].json;
const cacheKey = `${current.book_slug}:${current.chapter}`;
const cached = cache[cacheKey];

const updates = [];

if (cached) {
  if (cached.content_hash !== current.content_hash) {
    updates.push({
      ...current,
      change_type: 'modified',
      old_hash: cached.content_hash,
      new_hash: current.content_hash,
      action: 'content_changed'
    });
  }
} else {
  updates.push({
    ...current,
    change_type: 'new',
    old_hash: null,
    new_hash: current.content_hash,
    action: 'new_content'
  });
}

// Update cache
if (current.action === 'content_checked' && !current.error) {
  cache[cacheKey] = {
    url: current.url,
    content_hash: current.content_hash,
    last_modified: current.last_modified,
    content_type: 'text',
    timestamp: new Date().toISOString()
  };

  // Save updated cache
  try {
    fs.writeFileSync(cacheFile, JSON.stringify(cache, null, 2));
  } catch (error) {
    console.error('Error saving cache:', error.message);
  }
}

return updates.map(update => ({ json: update }));

const updates = [];

$node["Detect Content Changes"].json.forEach(item => {
  if (item.action === 'content_changed' || item.action === 'new_content') {
    updates.push({
      url: item.url,
      content_type: 'text',
      change_type: item.change_type,
      metadata: {
        book_slug: item.book_slug,
        chapter: item.chapter,
        last_modified: item.last_modified
      }
    });
  }
});

return [{
  json: {
    timestamp: new Date().toISOString(),
    source: 'n8n',
    updates: updates,
    trigger_type: 'scheduled'
  }
}];

const crypto = require('crypto');
const secret = process.env.EXTERNAL_UPDATE_WEBHOOK_SECRET || 'default-secret';
const payload = JSON.stringify($node["Aggregate Updates"].json);

const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

return [{ json: { signature: signature } }];

const updates = $node["Aggregate Updates"].json.updates || [];

if (updates.length === 0) {
  console.log('No updates detected, workflow completed successfully');
  return [{ json: { message: 'No updates found' } }];
}

console.log(`Found ${updates.length} content updates`);

// Check if we should trigger deployment
const shouldDeploy = updates.length >= 5; // Configurable threshold

return [{
  json: {
    updates_count: updates.length,
    trigger_deployment: shouldDeploy,
    message: `Found ${updates.length} updates, deployment: ${shouldDeploy ? 'YES' : 'NO'}`
  }
}];

